data = []
with open('2610.txt') as file:
    N = int(file.readline())

    for line in file:
        parts = line.strip().split()
        end = int(parts[0])+int(parts[1])
        event = {"start": int(parts[0]), "end": end}
        data.append(event)

events = sorted(data, key=lambda event: (event["end"], -event["start"]))

approved_events = [events[0]]

# Определяем подходящие мероприятия начало рассматриваемого
# должно быть позже конца последнего взятого мероприятия
for event in events[1:]:
    if event["start"] >= approved_events[-1]["end"]:
        approved_events.append(event)

# Самый длинный перерыв — разница между началом последнего
# и концом предпоследнего (последнее мероприятие можем сдвинуть дальше)
longest_break = 0
for event in events:
    if event["start"] >= approved_events[-2]["end"]:
        longest_break= max(longest_break,
                           event['start'] - approved_events[-2]["end"])

print(len(approved_events), longest_break)

with open('2611.txt') as file:
    N = int(file.readline())
    students = []
    for i in file:
        students.append(list(map(int, i.split())))

students.sort()

cnt = 1
ans = []
for i in range(N - 1):
    student1, student2 = students[i], students[i + 1]
    if student1[0] == student2[0]:
        if student1[1] == student2[1]:
            continue
        if abs(student2[1] - student1[1]) == 2:
            cnt += 1
        else:
            cnt = 1
    else:
        cnt = 1
    ans.append([cnt, student1[0]])

ans.sort(key=lambda x: (x[0], -x[1]))
print(ans[-1])

with open('2614.txt') as file:
    N, M = map(int, file.readline().split())
    boxes = []
    for line in file:
        line = line.split()
        if len(line) == 2:
            boxes.append((int(line[0]), 'red'))
            boxes.append((int(line[1]), 'blue'))
        else:
            boxes.append((int(line[0]), 'red'))

boxes.sort(reverse=True)
start_red = [max(boxes, key=lambda x: x[1] == 'red')]
start_blue = [max(boxes, key=lambda x: x[1] == 'blue')]

for box in boxes:
    if start_red[-1][1] != box[1] and start_red[-1][0] - box[0] >= 5:
        start_red.append(box)
    if start_blue[-1][1] != box[1] and start_blue[-1][0] - box[0] >= 5:
        start_blue.append(box)

ans = max(start_red, start_blue, key=len)
print(len(ans), ans[-1][0])

with open('2615.txt') as file:
    S, _ = map(int, file.readline().split())
    data = list(map(int, file))

data_sorted = sorted(data)

files = []
for i in data_sorted:
    if sum(files) + i <= S:
        files.append(i)

files = files[:-1]


for j in data_sorted[::-1]:
    if j <= S - sum(files):
        files.append(j)

